<section class="erp-card"><h2>بانک، صندوق و تنخواه</h2><?php self::search($cid,$p); ?><div class="erp-scroll"><table class="erp-table"><thead><tr><?php echo self::sortHead('code','کد').self::sortHead('name','نام'); ?><th>نوع</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($data['rows'] as $a): ?><tr><td><?php echo esc_html($a['code']); ?></td><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'cash_forecast','account_id'=>$a['id']])); ?>"><?php echo esc_html($a['name']); ?></a></td><td><?php echo esc_html(['bank'=>'بانک','cash'=>'صندوق','petty'=>'تنخواه'][$a['kind']]); ?></td><td><?php echo $a['is_active']?'فعال':'غیرفعال'; ?></td><td><?php if(Ctx::can('treasury_account.edit')): ?><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>$p,'edit'=>$a['id']])); ?>">ویرایش</a><?php endif; ?><?php if(Ctx::can('treasury_account.delete')): ?><form method="post" class="inline"><?php self::form('module_treasury_account_delete',$cid,$p,$a['id']); ?><button type="submit" class="btn btn-outline btn-sm">حذف بدون سابقه</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($data['pages'],$data['page']); ?></section>
<?php if(Ctx::can($edit?'treasury_account.edit':'treasury_account.create')): ?><section class="erp-card"><h3>ثبت/ویرایش حساب خزانه</h3><form method="post" class="erp-form"><?php self::form('module_treasury_account_save',$cid,$p,$edit);self::input('code','کد',$r['code']??'','text','required maxlength="30"');self::input('name','نام',$r['name']??'','text','required maxlength="190"');self::select('kind','نوع',['bank'=>'بانک','cash'=>'صندوق','petty'=>'تنخواه'],$r['kind']??'bank');foreach(['bank_name'=>'نام بانک','account_no'=>'شماره حساب','iban'=>'شبا IR + ۲۴ رقم'] as $k=>$label)self::input($k,$label,$r[$k]??'','text','maxlength="'.($k==='bank_name'?100:($k==='iban'?26:40)).'" dir="ltr"'); ?><label><input type="checkbox" name="is_active" value="1" <?php checked(self::value('is_active',$r['is_active']??1),1); ?>>فعال</label><p>مانده فقط از اسناد حسابداری محاسبه می‌شود؛ برای ماندهٔ اولیه، سند افتتاحیه با تفصیلی این حساب ثبت کنید.</p><button type="submit" class="btn btn-primary">ذخیرهٔ حساب</button></form></section><?php endif; ?>
